import { cn } from '../lib/cn';
import { FILE_TYPE_GLYPHS, type FileTypeGlyph } from './fileTypeGlyphs.generated';

// File-type icons from Fluent 2's System Icons (microsoft/fluentui-system-icons, MIT licence; owner decision, 2026-11-27): one consistent
// glyph style for every kind of file, each kind in its own colour, so every icon is the same size and the colour says the format. The
// glyphs are generated by scripts/sync-file-type-glyphs.mjs (fileTypeGlyphs.generated.ts), drawn inline in the filled style, at Microsoft's
// native 20 px drawing in rows and its 32 px drawing on tiles.

interface FileKind {
  name: string;
  glyph: FileTypeGlyph;
  /** The kind's colour: the glyph, and the tile's tint at low strength. */
  color: string;
  extensions: string[];
}

// In legend order. An extension in no kind is "Other", with the plain document glyph.
const KINDS: FileKind[] = [
  { name: 'Word', glyph: 'documentText', color: '#1d5bd6', extensions: ['docx', 'doc', 'docm', 'dotx', 'dot', 'odt'] },
  { name: 'PDF', glyph: 'documentPdf', color: '#c8322f', extensions: ['pdf'] },
  { name: 'Excel', glyph: 'documentData', color: '#137a43', extensions: ['xlsx', 'xls', 'xlsm', 'xlsb', 'xltx', 'csv', 'tsv', 'ods'] },
  { name: 'PowerPoint', glyph: 'slideText', color: '#c4441b', extensions: ['pptx', 'ppt', 'pptm', 'ppsx', 'potx', 'odp'] },
  { name: 'Text', glyph: 'documentOnePage', color: '#475569', extensions: ['txt', 'md', 'markdown', 'text', 'log'] },
  { name: 'Rich text', glyph: 'documentHeader', color: '#6d4bc2', extensions: ['rtf'] },
  { name: 'Images', glyph: 'image', color: '#0f766e', extensions: ['png', 'jpg', 'jpeg', 'gif', 'bmp', 'tif', 'tiff', 'webp', 'svg', 'heic'] },
  { name: 'Archives', glyph: 'archive', color: '#a16207', extensions: ['zip', '7z', 'rar', 'tar', 'gz', 'tgz', 'bz2'] },
  {
    name: 'Code',
    glyph: 'code',
    color: '#7c3aed',
    extensions: ['html', 'htm', 'xml', 'json', 'yaml', 'yml', 'js', 'ts', 'tsx', 'jsx', 'py', 'cs', 'java', 'c', 'cpp', 'h', 'sql', 'sh', 'css'],
  },
  { name: 'Email', glyph: 'mail', color: '#0e7490', extensions: ['msg', 'eml'] },
  { name: 'Video', glyph: 'video', color: '#be185d', extensions: ['mp4', 'mov', 'avi', 'mkv', 'webm', 'wmv'] },
  { name: 'Audio', glyph: 'musicNote', color: '#9333ea', extensions: ['mp3', 'wav', 'm4a', 'aac', 'flac', 'ogg', 'wma'] },
];
const OTHER: FileKind = { name: 'Other', glyph: 'document', color: '#5b6a80', extensions: [] };
const FOLDER: FileKind = { name: 'Folder', glyph: 'folder', color: '#b7791f', extensions: [] };

function keyOf(extension: string): string {
  return extension.replace(/^\./, '').toLowerCase();
}

/** The kind a file is, by its extension (or a folder). */
export function fileKindOf(extension: string, folder = false): FileKind {
  if (folder) return FOLDER;
  const key = keyOf(extension);
  return KINDS.find((kind) => kind.extensions.includes(key)) ?? OTHER;
}

/** The rendered size in px from the call site's Tailwind height class (`h-5` is 20 px); 20 when it names none. */
function sizeOf(className: string | undefined): number {
  const match = className?.match(/(?:^|\s)h-(\d+(?:\.\d+)?)(?:\s|$)/);
  return match ? Number(match[1]) * 4 : 20;
}

/** The glyph, drawn at Microsoft's own drawing for the size: 20 px in rows (24 px and smaller), 32 px on tiles. */
export function FileGlyph({ glyph, px, className, color }: { glyph: FileTypeGlyph; px: number; className?: string; color?: string }): React.ReactElement {
  const drawings: Partial<Record<20 | 32, readonly string[]>> = FILE_TYPE_GLYPHS[glyph];
  const size = px <= 24 ? (drawings[20] ? 20 : 32) : drawings[32] ? 32 : 20;
  return (
    <svg viewBox={`0 0 ${size} ${size}`} aria-hidden="true" focusable="false" className={cn('flex-none', className)} style={color ? { color } : undefined}>
      {drawings[size]!.map((d) => (
        <path key={d} d={d} fill="currentColor" />
      ))}
    </svg>
  );
}

/**
 * A file's icon: its kind's glyph in its colour. `tile` sets it on a soft tile of that colour (cards, legends, the uploaded document), the
 * glyph at two thirds of the tile; otherwise the glyph alone fills the size (rows, the SharePoint tree).
 */
export function FileTypeIcon({
  extension = '',
  folder = false,
  tile = false,
  className,
}: {
  extension?: string;
  folder?: boolean;
  tile?: boolean;
  className?: string;
}): React.ReactElement {
  const kind = fileKindOf(extension, folder);
  const px = sizeOf(className);
  if (!tile) return <FileGlyph glyph={kind.glyph} px={px} color={kind.color} className={className} />;
  return (
    <span
      aria-hidden="true"
      className={cn('grid flex-none place-items-center rounded-md', className)}
      style={{ color: kind.color, backgroundColor: `${kind.color}1f` }}
    >
      <FileGlyph glyph={kind.glyph} px={Math.round(px * 0.66)} className="h-2/3 w-2/3" />
    </span>
  );
}

export function fileTypeLabel(extension: string): string {
  return keyOf(extension).toUpperCase();
}

/** `extensions` sorted into their kinds, in legend order; the ones in no kind last, as "Other". */
export function fileTypeGroups(extensions: string[]): { name: string; glyph: FileTypeGlyph; color: string; extensions: string[] }[] {
  const keys = extensions.map(keyOf);
  const grouped = KINDS.map((kind) => ({ ...kind, extensions: keys.filter((key) => kind.extensions.includes(key)) })).filter(
    (kind) => kind.extensions.length > 0,
  );
  const other = keys.filter((key) => !KINDS.some((kind) => kind.extensions.includes(key)));
  return other.length ? [...grouped, { ...OTHER, extensions: other }] : grouped;
}

/** The file types a drop box takes, by group: equal tiles, each the group's icon, its name and the extensions it takes. */
export function FileTypeLegend({ extensions, label = 'File types you can drop' }: { extensions: string[]; label?: string }): React.ReactElement {
  return (
    <ul aria-label={label} className="mt-3 grid w-full max-w-xl grid-cols-2 gap-3 sm:grid-cols-4">
      {fileTypeGroups(extensions).map((group) => (
        <li
          key={group.name}
          className="file-legend-tile flex flex-col items-center gap-2 rounded-md border border-hairline bg-surface-alt px-2 pb-3 pt-3.5 transition-colors duration-fast"
        >
          <span className="grid h-12 w-12 place-items-center rounded-md" style={{ color: group.color, backgroundColor: `${group.color}1f` }}>
            <FileGlyph glyph={group.glyph} px={32} className="h-8 w-8" />
          </span>
          <span className="text-sm font-semibold text-ink-1">{group.name}</span>
          <span className="flex flex-wrap justify-center gap-1">
            {group.extensions.map((key) => (
              <span key={key} className="rounded-sm border border-hairline bg-surface px-1.5 font-mono text-micro text-ink-2">
                .{key}
              </span>
            ))}
          </span>
        </li>
      ))}
    </ul>
  );
}

/** The drop box's fan: four tiles (Text, PDF, Excel, Word) that deal in once, open a little on hover or focus, and wide while a file is dragged over. */
export function FileTypeFan({ open }: { open: boolean }): React.ReactElement {
  return (
    <span aria-hidden="true" className="file-fan" data-open={open || undefined}>
      {(['txt', 'pdf', 'xlsx', 'docx'] as const).map((extension) => (
        <FileTypeIcon key={extension} extension={extension} tile className="h-12 w-12 border border-surface shadow-raised" />
      ))}
    </span>
  );
}
